<?php
declare(strict_types=1);
final class Auth {
 public static function login(ApiClient $api,string $email,string $password):void{$r=$api->request('POST','/api/v1/auth/login',['email'=>$email,'password'=>$password]);if(empty($r['access_token'])||empty($r['refresh_token']))throw new ApiException('The API did not return a valid session.',502);session_regenerate_id(true);$_SESSION['access_token']=$r['access_token'];$_SESSION['refresh_token']=$r['refresh_token'];$_SESSION['user']=$r['user']??[];$_SESSION['authenticated_at']=time();}
 public static function logout(ApiClient $api):void{try{if(!empty($_SESSION['access_token']))$api->request('POST','/api/v1/auth/logout',null,$_SESSION['access_token']);}catch(Throwable){}$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain']??'',$p['secure'],$p['httponly']);}session_destroy();}
 public static function check():bool{return !empty($_SESSION['access_token']);} public static function requireLogin():void{if(!self::check())redirect('login.php');} public static function user():array{return is_array($_SESSION['user']??null)?$_SESSION['user']:[];} public static function accessToken():?string{return $_SESSION['access_token']??null;} public static function refreshToken():?string{return $_SESSION['refresh_token']??null;}
 public static function api(ApiClient $api,string $method,string $path,?array $body=null):array{try{return $api->request($method,$path,$body,self::accessToken());}catch(ApiException $e){if($e->status()!==401||!self::refreshToken())throw $e;$r=$api->request('POST','/api/v1/auth/refresh',['refresh_token'=>self::refreshToken()]);if(empty($r['access_token'])||empty($r['refresh_token'])){self::logout($api);throw new ApiException('Your session has expired. Please sign in again.',401);}$_SESSION['access_token']=$r['access_token'];$_SESSION['refresh_token']=$r['refresh_token'];return $api->request($method,$path,$body,self::accessToken());}}
}
